ROOT=Path(__file__).resolve().parent
SC7=ROOT/'scenario_candidates/scenario7'; EV=SC7/'EXPLORATEUR_PATH_CLOSURE_324.json'; results=[]
def check(name,ok,detail=None): results.append({'name':name,'status':'PASS' if ok else 'FAIL','detail':detail})
ev=json.loads(EV.read_text(encoding='utf-8')); layout=SC7/'source_layout.txt'; lines=layout.read_text(encoding='utf-8').split('\n')
def rh(ref):
    bits=ref.split('_'); a=int(bits[1][1:]); b=int(bits[2][1:]); return hashlib.sha256('\n'.join(lines[a-1:b]).encode()).hexdigest()
def match(r): return [rh(x) for x in r['source_refs']]==r['source_hashes']
