pdf=Path(os.environ.get('EXPLORATEUR_SOURCE_PDF','')); check('source_pdf_available_and_sha256_exact',pdf.is_file() and hashlib.sha256(pdf.read_bytes()).hexdigest()==ev['source']['pdf_sha256'],str(pdf))
