bad=json.loads(json.dumps(ev['start'])); bad['derived_from_clue_anchor']=True; check('clue_anchor_cannot_be_start',InvestigationStartEvidenceGateV4.validate(bad).get('code')=='CLUE_ANCHOR_IS_NOT_START_CAUSALITY')
mat=[ExplicitInvestigationProgressionGateV4.materialize(x) for x in ev['transitions']]; check('all_ten_progression_edges_materialized',len(mat)==10 and all(x.get('status')=='MATERIALIZED' for x in mat))
proof=SourceBackedInvestigationPathV4.prove(ev['start'],ev['transitions'],ev['terminal_scene']); check('complete_source_backed_path_proved',proof.get('status')=='PROVED' and len(proof.get('transition_ids',[]))==10); check('generic_execution_ledger_exact',proof.get('executed_state',{}).get('transition_ledger')==[x['transition_id'] for x in ev['transitions']]); check('no_clue_anchor_edges_used',proof.get('clue_anchor_edges_used')==0 and ev['anti_false_causality']['clue_scene_anchors_promoted_to_edges']==0); check('path_does_not_require_specific_clue_anchor',all(not x.get('requires_specific_clue_anchor') for x in ev['transitions'])); check('path_does_not_self_promote',proof.get('promotion_applied') is False and ev.get('pass_real') is False)
for name,mut,code in [('derived_clue_anchor_fails_closed',{'derived_from_clue_anchor':True},'CLUE_ANCHOR_NOT_CAUSAL_EDGE'),('specific_clue_gate_fails_closed',{'requires_specific_clue_anchor':True},'SPECIFIC_CLUE_ANCHOR_CANNOT_GATE_PATH'),('missing_manual_audit_fails_closed',{'source_language_audit':'UNVERIFIED'},'PROGRESSION_LANGUAGE_AUDIT_MISSING'),('ambiguous_target_fails_closed',{'target_binding_count':2},'PROGRESSION_TARGET_NOT_UNIQUE'),('inferred_transition_fails_closed',{'explicit_source_language':False},'PROGRESSION_SOURCE_NOT_EXPLICIT'),('editorial_reference_fails_closed',{'editorial_reference_only':True},'EDITORIAL_REFERENCE_IS_NOT_PROGRESSION')]:
    r=json.loads(json.dumps(ev['transitions'][3])); r.update(mut); check(name,ExplicitInvestigationProgressionGateV4.validate(r).get('code')==code)
