statuses={k:MultiScenarioStatusResolver.resolve(ROOT/'scenario_candidates',k) for k in ('scenario3','scenario4','scenario5','scenario6','scenario7')}; check('status_boundary_3_to_6_pass_7_blocked',all(statuses[k]['pass_real'] is True for k in ('scenario3','scenario4','scenario5','scenario6')) and statuses['scenario7']['pass_real'] is False)
